		sort(nums.begin(), nums.end());
		int n = nums.size();
		int l = 0;
		int r = nums.back() - nums.front();
		while (l <= r)
		{
			int cnt = 0;
			int j = 0;
			int m = l + (r - l) / 2;
			for (int i = 0; i < n; ++i)
			{
				while (j < n && nums[j] - nums[i] <= m) 
					++j;
				cnt += j - i - 1;
			}
			cnt >= k ? r = m - 1 : l = m + 1;
		}
		return l;
	}
